#include "seed/online_ai.hpp"
#include <cassert>
#include <iostream>
class Vault final:public seed::CredentialVault{public:bool getSecret(const std::string&r,std::string&s)const override{if(r!="test-key")return false;s="secret-value";return true;}};
class MockHttp final:public seed::HttpTransport{public:seed::HttpRequest last;seed::HttpResponse response{200,R"({"choices":[{"message":{"role":"assistant","content":"hello from cloud"}}],"usage":{"prompt_tokens":4,"completion_tokens":3}})"};bool postJson(const seed::HttpRequest&r,seed::HttpResponse&o,std::string&)override{last=r;o=response;return true;}};
int main(){seed::ProviderRegistry registry;std::string error;seed::ProviderConfig c{"openai","OpenAI","https://api.openai.com/v1","gpt-test","test-key",seed::ProviderKind::OpenAICompatible,true,30000,1024*1024,false};assert(registry.add(c,error));assert(!registry.add(c,error));assert(!registry.add({"bad","Bad","http://example.com","m","key"},error));auto route=seed::ProviderRouter::choose(true,true,true,registry);assert(route.target==seed::RouteTarget::Local);route=seed::ProviderRouter::choose(false,true,true,registry);assert(route.target==seed::RouteTarget::Online&&route.providerId=="openai");route=seed::ProviderRouter::choose(false,false,true,registry);assert(route.target==seed::RouteTarget::Unavailable);MockHttp http;Vault vault;auto adapter=seed::makeProviderAdapter(seed::ProviderKind::OpenAICompatible);seed::ChatRequest request{{{seed::ChatRole::System,"be helpful"},{seed::ChatRole::User,"say \"hello\""}},64,0.2F};auto result=adapter->generate(c,request,http,vault);assert(result.success&&result.text=="hello from cloud");assert(result.usage.reportedByProvider&&result.usage.inputTokens==4);assert(http.last.url=="https://api.openai.com/v1/chat/completions");assert(http.last.headers.at("Authorization")=="Bearer secret-value");assert(http.last.body.find("\\\"hello\\\"")!=std::string::npos);http.response.statusCode=401;result=adapter->generate(c,request,http,vault);assert(!result.success&&result.error.find("401")!=std::string::npos);auto noKey=c;noKey.credentialRef="missing";result=adapter->generate(noKey,request,http,vault);assert(!result.success);auto a=c;a.kind=seed::ProviderKind::Anthropic;a.baseUrl="https://api.anthropic.com";a.model="claude-test";http.response={200,R"({"content":[{"type":"text","text":"anthropic answer"}],"usage":{"input_tokens":2,"output_tokens":5}})"};result=seed::makeProviderAdapter(seed::ProviderKind::Anthropic)->generate(a,request,http,vault);assert(result.success&&result.text=="anthropic answer");auto g=c;g.kind=seed::ProviderKind::Gemini;g.baseUrl="https://generativelanguage.googleapis.com";g.model="gemini-test";http.response={200,R"({"candidates":[{"content":{"parts":[{"text":"gemini answer"}]}}],"usageMetadata":{"promptTokenCount":2,"candidatesTokenCount":6}})"};result=seed::makeProviderAdapter(seed::ProviderKind::Gemini)->generate(g,request,http,vault);assert(result.success&&result.text=="gemini answer");std::cout<<"SEED-X Phase 4 provider tests passed\n";}
